  /**
   * @method
   * @name deribit#fetchMyTrades
   * @description fetch all trades made by the user
   * @see https://docs.deribit.com/#private-get_user_trades_by_currency
   * @see https://docs.deribit.com/#private-get_user_trades_by_currency_and_time
   * @see https://docs.deribit.com/#private-get_user_trades_by_instrument
   * @see
   * https://docs.deribit.com/#private-get_user_trades_by_instrument_and_time
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch trades for
   * @param {int} [limit] the maximum number of trades structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=trade-structure}
   */
  std::shared_future<std::any>
  fetchMyTrades(std::any symbol = std::any{}, std::any since = std::any{},
                std::any limit = std::any{},
                std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any request = ccxt::dict{
                     {std::string("include_old"), true},
                 };
                 std::any market = std::any{};
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("count"),
                              limit); // default 10
                 }
                 std::any response = std::any{};
                 if (isTrue(isEqual(symbol, std::any{}))) {
                   std::any code = this->codeFromOptions(
                       std::string("fetchMyTrades"), params);
                   std::any currency = this->currency(code);
                   ::setValue(request, std::string("currency"),
                              ::getValue(currency, std::string("id")));
                   if (isTrue(isEqual(since, std::any{}))) {
                     response =
                         awaitValue(this->privateGetGetUserTradesByCurrency(
                             this->extend(request, params)));
                   } else {
                     ::setValue(request, std::string("start_timestamp"), since);
                     response = awaitValue(
                         this->privateGetGetUserTradesByCurrencyAndTime(
                             this->extend(request, params)));
                   }
                 } else {
                   market = this->market(symbol);
                   ::setValue(request, std::string("instrument_name"),
                              ::getValue(market, std::string("id")));
                   if (isTrue(isEqual(since, std::any{}))) {
                     response =
                         awaitValue(this->privateGetGetUserTradesByInstrument(
                             this->extend(request, params)));
                   } else {
                     ::setValue(request, std::string("start_timestamp"), since);
                     response = awaitValue(
                         this->privateGetGetUserTradesByInstrumentAndTime(
                             this->extend(request, params)));
                   }
                 }
                 //
                 //     {
                 //         "jsonrpc": "2.0",
                 //         "id": 9367,
                 //         "result": {
                 //             "trades": [
                 //                 {
                 //                     "trade_seq": 3,
                 //                     "trade_id": "ETH-34066",
                 //                     "timestamp": 1550219814585,
                 //                     "tick_direction": 1,
                 //                     "state": "open",
                 //                     "self_trade": false,
                 //                     "reduce_only": false,
                 //                     "price": 0.04,
                 //                     "post_only": false,
                 //                     "order_type": "limit",
                 //                     "order_id": "ETH-334607",
                 //                     "matching_id": null,
                 //                     "liquidity": "M",
                 //                     "iv": 56.83,
                 //                     "instrument_name": "ETH-22FEB19-120-C",
                 //                     "index_price": 121.37,
                 //                     "fee_currency": "ETH",
                 //                     "fee": 0.0011,
                 //                     "direction": "buy",
                 //                     "amount": 11
                 //                 },
                 //             ],
                 //             "has_more": true
                 //         }
                 //     }
                 //
                 std::any result = this->safeValue(
                     response, std::string("result"), ccxt::dict{});
                 std::any trades = this->safeList(result, std::string("trades"),
                                                  ccxt::list{});
                 return this->parseTrades(trades, market, since, limit);
               })
        .share();
  }

