  std::any parseGreeks(std::any greeks, std::any market = std::any{}) override {
    //
    //     {
    //         "estimated_delivery_price": 36552.72,
    //         "best_bid_amount": 0.2,
    //         "best_ask_amount": 9.1,
    //         "interest_rate": 0.0,
    //         "best_bid_price": 0.214,
    //         "best_ask_price": 0.219,
    //         "open_interest": 368.8,
    //         "settlement_price": 0.22103022,
    //         "last_price": 0.215,
    //         "bid_iv": 60.51,
    //         "ask_iv": 61.88,
    //         "mark_iv": 61.27,
    //         "underlying_index": "BTC-27SEP24",
    //         "underlying_price": 38992.71,
    //         "min_price": 0.1515,
    //         "max_price": 0.326,
    //         "mark_price": 0.2168,
    //         "instrument_name": "BTC-27SEP24-40000-C",
    //         "index_price": 36552.72,
    //         "greeks": {
    //             "rho": 130.63998,
    //             "theta": -13.48784,
    //             "vega": 141.90146,
    //             "gamma": 0.00002,
    //             "delta": 0.59621
    //         },
    //         "stats": {
    //             "volume_usd": 100453.9,
    //             "volume": 12.0,
    //             "price_change": -2.2727,
    //             "low": 0.2065,
    //             "high": 0.238
    //         },
    //         "state": "open",
    //         "timestamp": 1699578548021
    //     }
    //
    std::any timestamp = this->safeInteger(greeks, std::string("timestamp"));
    std::any marketId =
        this->safeString(greeks, std::string("instrument_name"));
    std::any symbol = this->safeSymbol(marketId, market);
    std::any stats =
        this->safeValue(greeks, std::string("greeks"), ccxt::dict{});
    return ccxt::dict{
        {std::string("symbol"), symbol},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
        {std::string("delta"), this->safeNumber(stats, std::string("delta"))},
        {std::string("gamma"), this->safeNumber(stats, std::string("gamma"))},
        {std::string("theta"), this->safeNumber(stats, std::string("theta"))},
        {std::string("vega"), this->safeNumber(stats, std::string("vega"))},
        {std::string("rho"), this->safeNumber(stats, std::string("rho"))},
        {std::string("bidSize"),
         this->safeNumber(greeks, std::string("best_bid_amount"))},
        {std::string("askSize"),
         this->safeNumber(greeks, std::string("best_ask_amount"))},
        {std::string("bidImpliedVolatility"),
         this->safeNumber(greeks, std::string("bid_iv"))},
        {std::string("askImpliedVolatility"),
         this->safeNumber(greeks, std::string("ask_iv"))},
        {std::string("markImpliedVolatility"),
         this->safeNumber(greeks, std::string("mark_iv"))},
        {std::string("bidPrice"),
         this->safeNumber(greeks, std::string("best_bid_price"))},
        {std::string("askPrice"),
         this->safeNumber(greeks, std::string("best_ask_price"))},
        {std::string("markPrice"),
         this->safeNumber(greeks, std::string("mark_price"))},
        {std::string("lastPrice"),
         this->safeNumber(greeks, std::string("last_price"))},
        {std::string("underlyingPrice"),
         this->safeNumber(greeks, std::string("underlying_price"))},
        {std::string("info"), greeks},
    };
  }

